# =========================================================
# CÁLCULOS CLÍNICOS
# =========================================================
def ckd_epi_2021(creatinine_mg_dl: float, age: float, sex_es: str) -> float:
    """CKD-EPI 2021 creatinina, sin raza."""
    female = sex_es == "Mujer"
    kappa = 0.7 if female else 0.9
    alpha = -0.241 if female else -0.302
    ratio = creatinine_mg_dl / kappa
    value = (
        142.0
        * min(ratio, 1.0) ** alpha
        * max(ratio, 1.0) ** -1.200
        * 0.9938 ** age
        * (1.012 if female else 1.0)
    )
    return max(0.0, value)


def friedewald_ldl(tc: float, hdl: float, tg: float) -> Optional[float]:
    if tg < 0 or tg >= 400:
        return None
    return max(0.0, tc - hdl - tg / 5.0)


def sampson_ldl(tc: float, hdl: float, tg: float) -> Optional[float]:
    if tg < 0 or tg > 800:
        return None
    non_hdl = tc - hdl
    ldl = (
        tc / 0.948
        - hdl / 0.971
        - (tg / 8.56 + (tg * non_hdl) / 2140.0 - (tg * tg) / 16100.0)
        - 9.44
    )
    return max(0.0, ldl)


def calculate_lipid_metrics(
    tc: float,
    hdl: float,
    tg: float,
    direct_ldl: Optional[float],
) -> LipidMetrics:
    non_hdl = max(0.0, tc - hdl)
    fw = friedewald_ldl(tc, hdl, tg)
    sp = sampson_ldl(tc, hdl, tg)
    if direct_ldl is not None and direct_ldl > 0:
        selected = direct_ldl
        method = "LDL-C directo informado"
    elif sp is not None:
        selected = sp
        method = "LDL-C calculado por Sampson/NIH"
    elif fw is not None:
        selected = fw
        method = "LDL-C calculado por Friedewald"
    else:
        selected = max(0.0, non_hdl)
        method = "LDL-C no estimable; se utiliza no-HDL-C como eje"
    remnant = max(0.0, non_hdl - selected) if selected <= non_hdl else None
    return LipidMetrics(
        non_hdl=non_hdl,
        ldl_friedewald=fw,
        ldl_sampson=sp,
        selected_ldl=selected,
        selected_method=method,
        remnant_cholesterol=remnant,
        tc_hdl_ratio=tc / hdl if hdl > 0 else math.nan,
        tg_hdl_ratio=tg / hdl if hdl > 0 else math.nan,
    )


def _prevent_features(inp: PreventInputs) -> Dict[str, float]:
    age10 = (inp.age - 55.0) / 10.0
    nonhdl = (inp.tc - inp.hdl) * 0.02586 - 3.5
    hdl = (inp.hdl * 0.02586 - 1.3) / 0.3
    sbp_low = (min(inp.sbp, 110.0) - 110.0) / 20.0
    sbp_high = (max(inp.sbp, 110.0) - 130.0) / 20.0
    bmi_low = (min(inp.bmi, 30.0) - 25.0) / 5.0
    bmi_high = (max(inp.bmi, 30.0) - 30.0) / 5.0
    egfr_low = (min(inp.egfr, 60.0) - 60.0) / -15.0
    egfr_high = (max(inp.egfr, 60.0) - 90.0) / -15.0
    dm = float(inp.diabetes)
    smoke = float(inp.smoker)
    anti = float(inp.antihtn)
    statin = float(inp.statin)

    missing_sdi = float(inp.sdi is None)
    sdi_46 = float(inp.sdi is not None and 4 <= inp.sdi <= 6)
    sdi_710 = float(inp.sdi is not None and 7 <= inp.sdi <= 10)
    missing_uacr = float(inp.uacr is None)
    ln_uacr = math.log(inp.uacr) if inp.uacr is not None and inp.uacr > 0 else 0.0
    missing_hba1c = float(inp.hba1c is None)
    hba1c_centered = (inp.hba1c - 5.3) if inp.hba1c is not None else 0.0

    return {
        "Age per 10 years": age10,
        "Age per 10 years squared": age10 * age10,
        "non-HDL-C per 1 mmol/L": nonhdl,
        "HDL-C per 0.3 mmol/L": hdl,
        "SBP <110 per 20 mmHg": sbp_low,
        "SBP ≥110 per 20 mmHg": sbp_high,
        "Diabetes": dm,
        "Current smoking": smoke,
        "BMI <30, per 5 kg/m2": bmi_low,
        "BMI 30+, per 5 kg/m2": bmi_high,
        "eGFR <60, per -15 ml": egfr_low,
        "eGFR 60+, per -15 ml": egfr_high,
        "Anti-hypertensive use": anti,
        "Statin use": statin,
        "Treated SBP ≥110 mm Hg per 20 mm Hg": sbp_high * anti,
        "Treated non-HDL-C": nonhdl * statin,
        "Age per 10yr * non-HDL-C per 1 mmol/L": age10 * nonhdl,
        "Age per 10yr * HDL-C per 0.3 mml/L": age10 * hdl,
        "Age per 10yr * SBP ≥110 mm Hg per 20 mmHg": age10 * sbp_high,
        "Age per 10yr * diabetes": age10 * dm,
        "Age per 10yr * current smoking": age10 * smoke,
        "Age per 10yr * BMI 30+ per 5 kg/m2": age10 * bmi_high,
        "Age per 10yr * eGFR <60, per -15 ml": age10 * egfr_low,
        "SDI decile categories 4-6 vs. 1-3": sdi_46,
        "SDI decile categories 7-10 vs. 1-3": sdi_710,
        "Missing SDI": missing_sdi,
        "ln-ACR, mg/g, per 1 ln unit": ln_uacr,
        "Missing ACR/PCR/Dipstick": missing_uacr,
        "HbA1c in DM, per 1%": hba1c_centered * dm,
        "HbA1c no DM, per 1%": hba1c_centered * (1.0 - dm),
        "Missing HbA1c": missing_hba1c,
        "Constant": 1.0,
    }


def validate_prevent_inputs(inp: PreventInputs) -> List[str]:
    issues: List[str] = []
    ranges = {
        "Edad": (inp.age, 30, 79),
        "Colesterol total": (inp.tc, 130, 320),
        "HDL-C": (inp.hdl, 20, 100),
        "PAS": (inp.sbp, 90, 200),
        "IMC": (inp.bmi, 18.5, 39.999),
        "eGFR": (inp.egfr, 15, 150),
    }
    for label, (value, low, high) in ranges.items():
        if not (low <= value <= high):
            issues.append(f"{label} fuera del rango validado ({low}–{high}).")
    if inp.uacr is not None and not (0.1 <= inp.uacr <= 25000):
        issues.append("UACR fuera del rango validado (0,1–25.000 mg/g).")
    if inp.hba1c is not None and not (3 <= inp.hba1c <= 15):
        issues.append("HbA1c fuera del rango validado (3–15%).")
    if inp.sdi is not None and not (1 <= inp.sdi <= 10):
        issues.append("SDI debe estar entre 1 y 10.")
    return issues


def calculate_prevent(inp: PreventInputs, horizon: int) -> Tuple[Dict[str, float], str, Dict[str, float]]:
    if horizon not in (10, 30):
        raise ValueError("El horizonte debe ser 10 o 30 años.")
    optional_present = any(v is not None for v in (inp.uacr, inp.hba1c, inp.sdi))
    model_key = ("full" if optional_present else "base") + str(horizon)
    features = _prevent_features(inp)
    sex = SEX_MODEL[inp.sex]
    results: Dict[str, float] = {}
    log_odds: Dict[str, float] = {}
    for outcome in OUTCOME_LABELS:
        coeff_key = f"{outcome}|{sex}"
        coefficients = PREVENT_COEFFICIENTS[model_key][coeff_key]
        linear = 0.0
        for coefficient_name, beta in coefficients.items():
            linear += beta * features.get(coefficient_name, 0.0)
        # logística estable
        risk = 1.0 / (1.0 + math.exp(-linear)) if linear >= 0 else math.exp(linear) / (1.0 + math.exp(linear))
        results[outcome] = 100.0 * risk
        log_odds[outcome] = linear
    label = "PREVENT completo (UACR/HbA1c/SDI con indicadores de faltantes)" if optional_present else "PREVENT base"
    return results, label, log_odds


def prevent_reference_self_test() -> Tuple[bool, str]:
    example = PreventInputs(
        age=50, sex="Mujer", tc=200, hdl=45, sbp=160,
        diabetes=True, smoker=False, bmi=35, egfr=90,
        antihtn=True, statin=False,
    )
    result, _, _ = calculate_prevent(example, 10)
    expected = {"Total CVD": 14.6839390956, "ASCVD": 9.1950897536, "Heart Failure": 8.0560967779}
    max_error = max(abs(result[k] - v) for k, v in expected.items())
    return max_error < 0.0001, f"Error máximo contra Tabla S25: {max_error:.8f} puntos porcentuales"


def risk_category(risk_10y: float) -> str:
    if risk_10y < 3:
        return "Bajo"
    if risk_10y < 5:
        return "Limítrofe"
    if risk_10y < 10:
        return "Intermedio"
    return "Alto"


def project_ldl(baseline_ldl: float, reductions: List[float]) -> float:
    projected = baseline_ldl
    for reduction in reductions:
        projected *= 1.0 - reduction
    return max(0.0, projected)


def build_therapy_plan(
    *,
    age: int,
    ldl: float,
    non_hdl: float,
    risk10: Optional[float],
    risk30: Optional[float],
    established_ascvd: bool,
    very_high_ascvd: bool,
    diabetes: bool,
    ckd_stage34: bool,
    hiv: bool,
    familial_hypercholesterolemia: bool,
    statin_intolerance: bool,
    tg: float,
    lpa_high: bool,
    apob: Optional[float],
    hs_crp: Optional[float],
    cac: Optional[int],
    risk_enhancers: List[str],
    pregnancy_or_planning: bool,
    active_liver_disease: bool,
    severe_renal_impairment: bool,
) -> TherapyPlan:
    first_line: List[str] = []
    escalation: List[str] = []
    precision: List[str] = []
    alerts: List[str] = []
    rules: List[str] = []
    ldl_goal: Optional[float] = None
    non_hdl_goal: Optional[float] = None
    reduction_goal: Optional[str] = None
    category = "No clasificable"
    indication = "Requiere evaluación clínica individual."
    intensity = "A definir"

    if established_ascvd:
        category = "Prevención secundaria – muy alto riesgo" if very_high_ascvd else "Prevención secundaria"
        indication = "Terapia hipolipemiante intensiva indicada; PREVENT no gobierna la decisión."
        intensity = "Alta intensidad / máxima tolerada"
        ldl_goal = 55.0 if very_high_ascvd else 70.0
        non_hdl_goal = 85.0 if very_high_ascvd else 100.0
        reduction_goal = "≥50% desde basal"
        first_line.append("Atorvastatina 40–80 mg o rosuvastatina 20–40 mg, o máxima dosis tolerada.")
        escalation.extend([
            "Agregar ezetimibe si no alcanza la meta.",
            "Si persiste fuera de meta, considerar inhibidor PCSK9 con beneficio cardiovascular; inclisiran o ácido bempedoico según adherencia, acceso e intolerancia.",
        ])
        rules.append("LLT-2026-04")
    elif ldl >= 190 or familial_hypercholesterolemia:
        category = "Hipercolesterolemia severa / probable HF"
        indication = "Estatina de máxima intensidad indicada independientemente de PREVENT."
        intensity = "Alta intensidad / máxima tolerada"
        ldl_goal = 70.0 if familial_hypercholesterolemia else 100.0
        non_hdl_goal = 100.0 if familial_hypercholesterolemia else 130.0
        reduction_goal = "≥50% desde basal"
        first_line.append("Atorvastatina 40–80 mg o rosuvastatina 20–40 mg; confirmar causas secundarias y fenotipo de hipercolesterolemia familiar.")
        escalation.extend([
            "Agregar ezetimibe precozmente si la proyección no alcanza objetivo.",
            "Considerar PCSK9/inclisiran o ácido bempedoico si persiste lejos de meta o hay intolerancia.",
        ])
        precision.append("Evaluar Dutch Lipid Clinic Network, examen de familiares y eventual estudio genético/cascada familiar.")
        rules.append("LLT-2026-02")
    else:
        special_group = 40 <= age <= 75 and (diabetes or ckd_stage34 or hiv)
        if risk10 is None and not special_group:
            category = "PREVENT no calculable"
            indication = "No automatizar la indicación farmacológica fuera del rango validado; individualizar según edad, exposición acumulada, comorbilidades y preferencias."
            intensity = "A definir clínicamente"
            first_line.append("Optimizar hábitos y completar la estratificación; considerar tratamiento según fenotipo lipídico y riesgo clínico global.")
        else:
            r = risk10 if risk10 is not None else 0.0
            category = risk_category(r) if risk10 is not None else "Grupo clínico de riesgo"
            if r >= 10:
                indication = "Iniciar terapia hipolipemiante."
                intensity = "Alta intensidad"
                ldl_goal, non_hdl_goal = 70.0, 100.0
                reduction_goal = "≥50%"
                first_line.append("Atorvastatina 40–80 mg o rosuvastatina 20–40 mg, individualizando tolerancia y función renal/hepática.")
                rules.extend(["LLT-2026-01", "LLT-2026-02", "LLT-2026-03"])
            elif r >= 5:
                indication = "Iniciar estatina después de discusión clínica compartida."
                intensity = "Al menos moderada; alta si se ubica en el extremo superior o hay potenciadores"
                ldl_goal, non_hdl_goal = 100.0, 130.0
                reduction_goal = "30–49%; considerar ≥50% en extremo alto"
                first_line.append("Atorvastatina 10–20 mg, rosuvastatina 5–10 mg o alternativa moderada; escalar según meta y potenciadores.")
                rules.extend(["LLT-2026-01", "LLT-2026-02", "LLT-2026-03"])
            elif r >= 3:
                indication = "Estatina moderada razonable tras discusión médico–paciente y evaluación de potenciadores/CAC."
                intensity = "Moderada"
                ldl_goal, non_hdl_goal = 100.0, 130.0
                reduction_goal = "30–49%"
                first_line.append("Estatina de intensidad moderada; si la decisión es incierta, personalizar con potenciadores y CAC.")
                rules.extend(["LLT-2026-01", "LLT-2026-02", "LLT-2026-03"])
            elif 30 <= age <= 59 and (160 <= ldl < 190 or (risk30 is not None and risk30 >= 10)):
                indication = "Aunque el riesgo a 10 años es bajo, una estatina moderada es razonable por exposición acumulada."
                intensity = "Moderada"
                ldl_goal, non_hdl_goal = 100.0, 130.0
                reduction_goal = "30–49%"
                first_line.append("Estatina moderada, priorizando reducción de exposición acumulativa a lipoproteínas aterogénicas.")
                rules.extend(["LLT-2026-01", "LLT-2026-02"])
            elif special_group:
                indication = "Terapia hipolipemiante recomendada por grupo de alto riesgo clínico, aun con PREVENT bajo."
                intensity = "Al menos moderada; graduar por PREVENT y potenciadores"
                ldl_goal, non_hdl_goal = 100.0, 130.0
                reduction_goal = "30–49% o mayor según riesgo"
                first_line.append("Iniciar estatina al menos moderada; considerar alta intensidad si PREVENT/potenciadores lo justifican.")
                rules.append("LLT-2026-05")
            else:
                indication = "Priorizar intervención intensiva sobre hábitos; farmacoterapia no automática."
                intensity = "No obligatoria"
                first_line.append("Optimizar alimentación, actividad física, peso, presión arterial, glucemia y tabaquismo; reevaluar perfil lipídico.")
                rules.append("LLT-2026-01")

    if statin_intolerance:
        alerts.append("Intolerancia atribuida a estatinas: documentar síntomas, CK si corresponde, interacciones, hipotiroidismo y estrategia de reexposición.")
        precision.extend([
            "Ensayar otra estatina, menor dosis o esquema intermitente; pitavastatina/pravastatina/rosuvastatina pueden ser alternativas según perfil.",
            "Usar ezetimibe y considerar ácido bempedoico o terapia PCSK9 si no se alcanza la meta con la dosis tolerada.",
        ])

    if ldl_goal is not None and ldl > ldl_goal:
        escalation.append(f"LDL-C actual {ldl:.0f} mg/dL: se encuentra {ldl - ldl_goal:.0f} mg/dL por encima de la meta propuesta.")
    if non_hdl_goal is not None and non_hdl > non_hdl_goal:
        escalation.append(f"No-HDL-C actual {non_hdl:.0f} mg/dL: persiste por encima de la meta de {non_hdl_goal:.0f} mg/dL.")

    if lpa_high:
        precision.append("Lp(a) elevada: intensificar control de LDL-C/ApoB y del resto de factores; las medidas de estilo de vida no normalizan Lp(a).")
        rules.append("LPA-2026-01")
    if apob is not None:
        precision.append(f"ApoB {apob:.0f} mg/dL: interpretar discordancia con LDL-C/no-HDL-C para estimar carga de partículas.")
        rules.append("APOB-2026-01")
    if hs_crp is not None and hs_crp >= 2:
        precision.append("hs-CRP ≥2 mg/L: potenciador de riesgo; descartar infección/inflamación aguda antes de usarlo para reclasificar.")
    if cac is not None:
        if cac == 0:
            precision.append("CAC 0: puede apoyar diferir farmacoterapia en algunos escenarios limítrofes/intermedios, salvo excepciones de alto riesgo.")
        elif cac > 0:
            precision.append(f"CAC {cac}: evidencia de aterosclerosis subclínica que favorece iniciar o intensificar LLT.")
    precision.extend(risk_enhancers)

    if tg >= 1000:
        alerts.append("TG ≥1000 mg/dL: riesgo de pancreatitis. Activar manejo urgente de causas secundarias, dieta muy baja en grasa y tratamiento específico de TG.")
        escalation.append("Considerar fenofibrato y/o omega-3 de prescripción; evitar gemfibrozilo junto con estatina por mayor riesgo de miopatía.")
        rules.append("TG-2026-01")
    elif tg >= 500:
        alerts.append("TG ≥500 mg/dL: priorizar prevención de pancreatitis, causas secundarias y control glucémico/alcohol.")
        rules.append("TG-2026-01")
    elif tg >= 150:
        precision.append("Hipertrigliceridemia residual: la estatina sigue siendo la base; evaluar elegibilidad para icosapento etilo sólo en perfiles clínicos de alto riesgo compatibles.")

    if pregnancy_or_planning:
        alerts.append("Embarazo, lactancia o búsqueda activa: no automatizar indicación; requiere decisión especializada y revisión individual de cada fármaco.")
    if active_liver_disease:
        alerts.append("Enfermedad hepática activa/descompensada: revisar etiología y seguridad antes de iniciar o intensificar estatina.")
    if severe_renal_impairment:
        alerts.append("ERC avanzada: ajustar selección/dosis y controlar interacciones; rosuvastatina y fibratos requieren especial cautela.")

    # Quitar duplicados preservando orden
    def uniq(items: List[str]) -> List[str]:
        return list(dict.fromkeys(items))

    return TherapyPlan(
        category=category,
        indication=indication,
        statin_intensity=intensity,
        ldl_goal=ldl_goal,
        non_hdl_goal=non_hdl_goal,
        reduction_goal=reduction_goal,
        first_line=uniq(first_line),
        escalation=uniq(escalation),
        precision_actions=uniq(precision),
        safety_alerts=uniq(alerts),
        rule_ids=uniq(rules),
    )


def make_html_report(payload: Dict[str, Any]) -> bytes:
    p = payload
    risks = p.get("prevent", {})
    plan = p["plan"]
    rows = "".join(
        f"<tr><td>{OUTCOME_LABELS.get(k,k)}</td><td>{v:.1f}%</td></tr>"
        for k, v in risks.get("10_year", {}).items()
    )
    items = lambda xs: "".join(f"<li>{x}</li>" for x in xs) or "<li>No registrado</li>"
    html = f"""<!doctype html><html lang='es'><head><meta charset='utf-8'>
    <style>body{{font-family:Arial,sans-serif;margin:34px;color:#172033}}h1{{color:#0b4f8a}}h2{{color:#0f766e;border-bottom:1px solid #ddd;padding-bottom:5px}}table{{border-collapse:collapse;width:100%}}td,th{{border:1px solid #ddd;padding:7px}}.box{{background:#f6f9fc;border-left:5px solid #0b4f8a;padding:12px;margin:10px 0}}small{{color:#555}}</style></head><body>
    <h1>{APP_NAME}</h1><small>{AUTOR_APP} · {APP_VERSION}</small>
    <h2>Paciente</h2><p><b>{p['patient']['name']}</b> · ID: {p['patient']['id']} · Fecha: {p['patient']['date']}</p>
    <h2>Perfil lipídico</h2><table><tr><th>Variable</th><th>Resultado</th></tr>
    <tr><td>LDL-C seleccionado</td><td>{p['lipids']['selected_ldl']:.1f} mg/dL ({p['lipids']['selected_method']})</td></tr>
    <tr><td>No-HDL-C</td><td>{p['lipids']['non_hdl']:.1f} mg/dL</td></tr>
    <tr><td>Triglicéridos</td><td>{p['raw']['tg']:.1f} mg/dL</td></tr></table>
    <h2>PREVENT</h2><p>{risks.get('model','No calculado')}</p><table><tr><th>Resultado</th><th>10 años</th></tr>{rows}</table>
    <h2>Decisión farmacológica</h2><div class='box'><b>{plan['category']}</b><br>{plan['indication']}<br><b>Intensidad:</b> {plan['statin_intensity']}</div>
    <p><b>Meta LDL-C:</b> {plan['ldl_goal'] if plan['ldl_goal'] is not None else 'Individualizar'} mg/dL · <b>Meta no-HDL-C:</b> {plan['non_hdl_goal'] if plan['non_hdl_goal'] is not None else 'Individualizar'} mg/dL · <b>Reducción:</b> {plan['reduction_goal'] or 'Individualizar'}</p>
    <h3>Primera línea</h3><ul>{items(plan['first_line'])}</ul><h3>Escalamiento</h3><ul>{items(plan['escalation'])}</ul><h3>Personalización</h3><ul>{items(plan['precision_actions'])}</ul><h3>Alertas</h3><ul>{items(plan['safety_alerts'])}</ul>
    <p><small>Herramienta de apoyo a la decisión clínica. No reemplaza juicio médico, verificación de prospectos locales, interacciones, preferencias, costo ni seguimiento.</small></p>
    </body></html>"""
    return html.encode("utf-8")


def make_pdf_report(payload: Dict[str, Any]) -> Optional[bytes]:
    try:
        from reportlab.lib import colors
        from reportlab.lib.enums import TA_CENTER
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.lib.units import cm
        from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak
    except Exception:
        return None

    buffer = io.BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=A4, rightMargin=1.5*cm, leftMargin=1.5*cm, topMargin=1.4*cm, bottomMargin=1.4*cm)
    styles = getSampleStyleSheet()
    styles.add(ParagraphStyle(name="TitleCenter", parent=styles["Title"], alignment=TA_CENTER, textColor=colors.HexColor("#0B4F8A")))
    story = [Paragraph(APP_NAME, styles["TitleCenter"]), Paragraph(AUTOR_APP, styles["Normal"]), Spacer(1, 10)]
    patient = payload["patient"]
    story.append(Paragraph(f"<b>Paciente:</b> {patient['name']} &nbsp;&nbsp; <b>ID:</b> {patient['id']} &nbsp;&nbsp; <b>Fecha:</b> {patient['date']}", styles["Normal"]))
    story.append(Spacer(1, 10))
    lip = payload["lipids"]
    data = [["LDL-C", "No-HDL-C", "TG", "Método LDL"], [f"{lip['selected_ldl']:.1f}", f"{lip['non_hdl']:.1f}", f"{payload['raw']['tg']:.1f}", lip['selected_method']]]
    table = Table(data, colWidths=[2.2*cm, 2.2*cm, 2.2*cm, 9*cm])
    table.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#0F766E")),("TEXTCOLOR",(0,0),(-1,0),colors.white),("GRID",(0,0),(-1,-1),.5,colors.grey),("VALIGN",(0,0),(-1,-1),"TOP"),("FONTSIZE",(0,0),(-1,-1),8)]))
    story.extend([Paragraph("Perfil lipídico", styles["Heading2"]), table, Spacer(1, 10)])
    prevent = payload.get("prevent", {})
    story.append(Paragraph("PREVENT", styles["Heading2"]))
    story.append(Paragraph(prevent.get("model", "No calculado"), styles["Normal"]))
    if prevent.get("10_year"):
        pdata = [["Resultado", "10 años", "30 años"]]
        for key in OUTCOME_LABELS:
            pdata.append([OUTCOME_LABELS[key], f"{prevent['10_year'].get(key, math.nan):.1f}%", f"{prevent.get('30_year',{}).get(key, math.nan):.1f}%"])
        pt = Table(pdata, colWidths=[9*cm,3*cm,3*cm])
        pt.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#0B4F8A")),("TEXTCOLOR",(0,0),(-1,0),colors.white),("GRID",(0,0),(-1,-1),.5,colors.grey),("FONTSIZE",(0,0),(-1,-1),8)]))
        story.append(pt)
    plan = payload["plan"]
    story.extend([Spacer(1, 10), Paragraph("Decisión farmacológica", styles["Heading2"]), Paragraph(f"<b>{plan['category']}</b>: {plan['indication']}", styles["BodyText"]), Paragraph(f"<b>Intensidad:</b> {plan['statin_intensity']} &nbsp; <b>Meta LDL-C:</b> {plan['ldl_goal'] or 'individualizar'} &nbsp; <b>Meta no-HDL-C:</b> {plan['non_hdl_goal'] or 'individualizar'}", styles["BodyText"])])
    for title, key in [("Primera línea","first_line"),("Escalamiento","escalation"),("Lipidología de precisión","precision_actions"),("Alertas","safety_alerts")]:
        story.append(Paragraph(title, styles["Heading3"]))
        values = plan[key] or ["Sin elementos adicionales."]
        for v in values:
            story.append(Paragraph("• " + v, styles["BodyText"]))
    story.extend([Spacer(1,10), Paragraph("Herramienta de apoyo a la decisión clínica. Verificar contraindicaciones, interacciones, prospectos locales y preferencias del paciente.", styles["Italic"])])
    doc.build(story)
    return buffer.getvalue()

